.sosw button{position:absolute;inset:14px;border-radius:50%;border:0;background:radial-gradient(circle at 32% 24%,#F0505C,#B5121F 78%);color:#fff;font:700 38px 'Barlow Semi Condensed',sans-serif;touch-action:none;user-select:none;-webkit-user-select:none;cursor:pointer;box-shadow:0 10px 22px rgba(216,33,47,.45);line-height:1}.sosw button small{display:block;font:600 11px 'Hind Siliguri',sans-serif;margin-top:4px}.sosw button.ok{background:radial-gradient(circle at 32% 24%,#5B8CFF,#1D4ED8 80%)}
