.ctl{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.ctl button{border:0;border-radius:14px;padding:12px 20px;font:700 15px 'Inter',sans-serif;cursor:pointer;background:#E1EAFF;color:#0F2557}.ctl .go{background:#1D4ED8;color:#fff}
