{t:'10. Driver: if there is an emergency',d:'Police can check the bus, driver name, ID and licence at any time.',h:'A bus can be suspended by traffic police. Passengers are refunded automatically.',tab:'',
 s:()=>head+'<h4>Bus check</h4><div class="row"><span><b>Driver</b><br>Nazrul Islam</span><span class="f"><b>OK</b>licence valid</span></div><div class="row"><span><b>Plate</b><br>DHAKA-METRO-BA-15-7788</span><span class="f"><b>OK</b></span></div><div class="btn1 r">Suspend bus (police)</div>'}]};
let role='p',i=0,timer=null;const $=id=>document.getElementById(id);
function sosInit(){const b=$('sb'),r=$('rg'),C=339.3;let t0=0,raf=0,done=0;
 const tick=()=>{const p=Math.min(1,(performance.now()-t0)/3000);r.style.strokeDashoffset=C*(1-p);if(p>=1){t0=0;done=1;b.className='ok';b.innerHTML='SENT ✓<small>পাঠানো হয়েছে</small>';$('sr').innerHTML='<div class="ok1" style="text-align:left">✓ Staff and traffic police alerted<br>✓ Your bus company notified<br>✓ SMS sent to 2 emergency contacts<br><b>If you are in danger, call 999 now.</b></div>';return}raf=requestAnimationFrame(tick)};
 const st=e=>{e.preventDefault();if(done||t0)return;t0=performance.now();raf=requestAnimationFrame(tick)};const en=()=>{if(!done&&t0){cancelAnimationFrame(raf);t0=0;r.style.strokeDashoffset=C}};
 b.addEventListener('pointerdown',st);['pointerup','pointerleave','pointercancel'].forEach(v=>b.addEventListener(v,en))}
function show(){const a=S[role];if(i>=a.length)i=0;const s=a[i];$('pg').innerHTML=s.s();$('tb').innerHTML=s.tab?tab(s.tab=='s'?'':s.tab):'';$('tt').innerHTML=s.t;$('do').innerHTML=s.d;$('hp').innerHTML=s.h;if(s.after)s.after();
 $('nums').innerHTML=a.map((x,k)=>'<button class="'+(k==i?'on':'')+'" data-i="'+k+'">'+(role=='p'?k+1:k+8)+'</button>').join('')}
$('nums').onclick=e=>{if(e.target.dataset.i!=null){i=+e.target.dataset.i;show()}};
$('nx').onclick=()=>{i=(i+1)%S[role].length;show()};$('bk').onclick=()=>{i=(i-1+S[role].length)%S[role].length;show()};
$('ap').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('ap').textContent='▶ Auto play'}else{$('ap').textContent='❚❚ Stop';timer=setInterval(()=>{i=(i+1)%S[role].length;show()},4500)}};
document.querySelectorAll('.sw button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sw button').forEach(x=>x.classList.remove('on'));b.classList.add('on');role=b.dataset.r;i=0;show()});
show();
</script>
